'use strict';

// MODULES //

import emptyLike from '@stdlib/ndarray-base-empty-like';
import fill from '@stdlib/ndarray-base-fill';


// MAIN //

/**
* Creates a ones-filled ndarray having the same shape and data type as a provided ndarray.
*
* @param {ndarray} x - input array
* @returns {ndarray} ndarray
*
* @example
* import getShape from '@stdlib/ndarray-shape';
* import getDType from '@stdlib/ndarray-dtype';
* import ones from '@stdlib/ndarray-base-ones';
*
* var x = ones( 'float32', [ 2, 2 ], 'row-major' );
* // returns <ndarray>[ [ 1.0, 1.0 ], [ 1.0, 1.0 ] ]
*
* var y = onesLike( x );
* // returns <ndarray>[ [ 1.0, 1.0 ], [ 1.0, 1.0 ] ]
*
* var sh = getShape( y );
* // returns [ 2, 2 ]
*
* var dt = String( getDType( y ) );
* // returns 'float32'
*/
function onesLike( x ) {
	return fill( emptyLike( x ), 1.0 );
}


// EXPORTS //

export default onesLike;
